#include "gpu/shader_cache.h"
#include <fstream>
#include <cassert>
#include <iostream>
#include <thread>
int main(int argc,char**argv){assert(argc==2);namespace fs=std::filesystem;using C=urban::gpu::ShaderCache;fs::path root=argv[1];std::string compiler(64,'a');C c;assert(c.Open(root,compiler));std::vector<uint32_t> code={0x07230203,0x00010300,0,1,0,0x00010000},got;assert(c.Load("author shader","main",0,got)==C::Result::Miss);assert(c.Store("author shader","main",0,code));assert(c.Load("author shader","main",0,got)==C::Result::Hit&&got==code);assert(c.Load("changed shader","main",0,got)==C::Result::Miss);assert(c.Load("author shader","main",1,got)==C::Result::Miss);assert(c.Load("author shader","other",0,got)==C::Result::Miss);C other;assert(other.Open(root,std::string(64,'b')));assert(other.Load("author shader","main",0,got)==C::Result::Miss);auto entry=*fs::directory_iterator(root/compiler);{std::fstream f(entry.path(),std::ios::binary|std::ios::in|std::ios::out);f.seekp(145);f.put(99);}assert(c.Load("author shader","main",0,got)==C::Result::Invalid);assert(c.Store("author shader","main",0,code));fs::resize_file(entry.path(),5);assert(c.Load("author shader","main",0,got)==C::Result::Invalid);fs::remove(entry.path());fs::create_symlink(root/"outside",entry.path());assert(c.Load("author shader","main",0,got)==C::Result::Invalid);assert(c.Store("author shader","main",0,code));assert(!fs::exists(root/"outside"));C bad;fs::create_directory_symlink(root/compiler,root/"link");assert(!bad.Open(root/"link",compiler));std::vector<uint32_t> invalid(5);assert(!c.Store("bad","main",0,invalid));assert(!c.Store("empty","main",0,{}));C parallel;assert(parallel.Open(root,compiler));std::thread a([&]{for(int n=0;n<16;n++)c.Store("concurrent","main",0,code);});std::thread b([&]{for(int n=0;n<16;n++)parallel.Store("concurrent","main",0,code);});a.join();b.join();assert(c.Load("concurrent","main",0,got)==C::Result::Hit&&got==code);auto huge=root/compiler/"budget.spv";{std::ofstream f(huge);f.put(0);}fs::resize_file(huge,65u<<20);assert(!c.Store("over-budget","main",0,code));fs::remove(huge);std::cout<<"Shader cache: cold/warm identity, source/stage/entry/compiler separation, corruption/truncation/symlink recovery and SPIR-V bounds passed\n";}
